import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Accelerating PMEM Device operations in bluestore with hardware based memory offloading technique","description":"","frontmatter":{"title":"Accelerating PMEM Device operations in bluestore with hardware based memory offloading technique","date":"2022-11-14T00:00:00.000Z","updated":"2022-11-15T00:00:00.000Z","tags":["Ceph","PMEM","hardware offloading","performance optimization","bluestore"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Accelerating_PMEM_Device_operations_in_bluestore_with_hardware_based_memory_offloading_technique.md","filePath":"posts/2022/Accelerating_PMEM_Device_operations_in_bluestore_with_hardware_based_memory_offloading_technique.md","lastUpdated":1780459816000}'),o={name:"posts/2022/Accelerating_PMEM_Device_operations_in_bluestore_with_hardware_based_memory_offloading_technique.md"};function r(n,e,h,s,d,c){return i(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-通过硬件卸载技术加速ceph中持久内存设备操作" tabindex="-1">会议主题：通过硬件卸载技术加速Ceph中持久内存设备操作 <a class="header-anchor" href="#会议主题-通过硬件卸载技术加速ceph中持久内存设备操作" aria-label="Permalink to &quot;会议主题：通过硬件卸载技术加速Ceph中持久内存设备操作&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-self-outcome虚拟会议" tabindex="-1">会议地点：Self-Outcome虚拟会议 <a class="header-anchor" href="#会议地点-self-outcome虚拟会议" aria-label="Permalink to &quot;会议地点：Self-Outcome虚拟会议&quot;">​</a></h4><h4 id="主讲人-姓名" tabindex="-1">主讲人：[姓名] <a class="header-anchor" href="#主讲人-姓名" aria-label="Permalink to &quot;主讲人：[姓名]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>背景与问题介绍</strong></p><ul><li>随着非易失性内存设备（PMEM）的普及，如Intel Optane内存，数据中心中CPU资源在操作这些设备时成为瓶颈。</li><li>使用应用程序直接模式时，CPU需要处理更多的读写操作，导致资源紧张。</li><li>持久内存设备缺乏DMA直接内存访问能力，导致CPU负载增加。</li></ul></li><li><p><strong>提出的解决方案</strong></p><ul><li>利用硬件卸载技术，如Intel的io80、iox和DSA（数据流加速器），来减轻CPU的负担。</li><li>DSA是一种高性能的数据复制和转换加速器，将用于优化数据移动和其他操作。</li></ul></li><li><p><strong>DSA的深度启用</strong></p><ul><li>介绍了如何在系统中启用DSA，包括使用同步API和异步API来卸载CPU操作。</li><li>目前已在Brewster中实现了同步模式的DSA支持，并计划在未来扩展到异步模式。</li></ul></li><li><p><strong>结论与未来工作</strong></p><ul><li>通过硬件卸载技术，特别是利用DSA和DML库，可以有效减轻CPU在持久内存操作中的压力。</li><li>未来工作包括优化Ceph存储系统中的持久内存操作，并探索其他卸载设备如FPGA的应用。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了硬件卸载技术在缓解持久内存设备操作中CPU瓶颈的有效性。</li><li>确定了下一步在Ceph存储系统中实施和优化DSA技术的具体步骤。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>完善DSA的异步模式支持。</li><li>在Ceph存储系统中实施DSA技术，并评估其性能改进。</li><li>探索其他硬件卸载设备如FPGA在持久内存操作中的应用潜力。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>详细的性能报告将在SPI发布后提供。</li></ul><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>[参会人员名单]</li></ul><h4 id="会议记录人" tabindex="-1">会议记录人： <a class="header-anchor" href="#会议记录人" aria-label="Permalink to &quot;会议记录人：&quot;">​</a></h4><ul><li>[记录人姓名]</li></ul>',17)])])}const p=a(o,[["render",r]]);export{u as __pageData,p as default};
